VOWELS = "aeiou"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))


def _translate_word(word):
    # Rule 1: begins with a vowel, or with "xr" or "yt".
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Rules 2-4: move the leading consonant cluster to the end.
    # The cluster ends at the first vowel, at "qu", or at a "y"
    # that is not the first letter.
    i = 0
    while i < len(word):
        if word[i] in VOWELS:
            break
        if word[i] == "q" and i + 1 < len(word) and word[i + 1] == "u":
            i += 2
            break
        if word[i] == "y" and i > 0:
            break
        i += 1

    return word[i:] + word[:i] + "ay"
